#if HAVE_NETLINK
/*
 * Persistent (daemon-like) mode for netlink-configured devices.
 *
 * The kernel nbd driver broadcasts NBD_CMD_LINK_DEAD messages on the
 * "nbd_mc_group" generic netlink multicast group whenever it detects
 * that a connection has died.  We subscribe to that group, and when we
 * see the link for our device go down, we reconnect to the server
 * (with exponential backoff) and hand the new sockets to the kernel
 * through NBD_CMD_RECONFIGURE, so that in-flight requests can be
 * retried and I/O resumes.
 */

/* How long the kernel keeps waiting for a reconnect before failing
 * pending I/O, when the user didn't specify a value of their own. */
#define NBD_DEFAULT_DEAD_CONN_TIMEOUT	30

/* Delay between attempts to reconnect or reconfigure, in seconds. */
#define NBD_PERSIST_INITIAL_BACKOFF	1
#define NBD_PERSIST_MAX_BACKOFF		180

/* How often, in seconds, to poll the device for its status even when
 * no link-dead events arrive (an external disconnect doesn't generate
 * any, and we want to notice it and quit). */
#define NBD_PERSIST_POLL_INTERVAL	30

static volatile sig_atomic_t persist_running = 1;

static void persist_stop(int sig G_GNUC_UNUSED) {
	persist_running = 0;
}

struct persist_state {
	int index;
	const char *identifier;
	int link_dead;
};

static int persist_event_callback(struct nl_msg *msg, void *arg) {
	struct genlmsghdr *gnlh = nlmsg_data(nlmsg_hdr(msg));
	struct nlattr *msg_attr[NBD_ATTR_MAX + 1];
	struct persist_state *state = arg;

	if (nla_parse(msg_attr, NBD_ATTR_MAX, genlmsg_attrdata(gnlh, 0),
		      genlmsg_attrlen(gnlh, 0), NULL))
		return NL_OK;

	if (gnlh->cmd != NBD_CMD_LINK_DEAD)
		return NL_OK;
	if (!msg_attr[NBD_ATTR_INDEX])
		return NL_OK;
	if ((int)nla_get_u32(msg_attr[NBD_ATTR_INDEX]) != state->index)
		return NL_OK;

	state->link_dead = 1;
	return NL_OK;
}

