/*
 * Persistent mode for netlink-configured devices.
 *
 * The kernel nbd driver broadcasts an NBD_CMD_LINK_DEAD message, carrying
 * the device index, on the "nbd_mc_group" generic netlink multicast group
 * whenever it notices one of our connections has died. We subscribe to
 * that group and, upon receiving such a notification for our device,
 * reconnect to the server (with exponential backoff) and hand the new
 * sockets to the kernel via NBD_CMD_RECONFIGURE, so that queued I/O can
 * be retried over the new connections.
 */

/* Delay before the first reconnection attempt, and upper bound for the
 * exponential backoff, in seconds. */
#define NBD_PERSIST_INITIAL_BACKOFF	1
#define NBD_PERSIST_MAX_BACKOFF		180

/* While waiting for link-dead events, how often (in seconds) to check
 * whether the device was disconnected out from under us (e.g. through
 * "nbd-client -d"); no events are sent for those. */
#define NBD_PERSIST_POLL_INTERVAL	30

static volatile sig_atomic_t persist_running = 1;

static void persist_stop(int sig G_GNUC_UNUSED) {
	persist_running = 0;
}

struct persist_state {
	int index;
	int link_dead;
};

static int persist_event_callback(struct nl_msg *msg, void *arg) {
	struct genlmsghdr *gnlh = nlmsg_data(nlmsg_hdr(msg));
	struct nlattr *msg_attr[NBD_ATTR_MAX + 1];
	struct persist_state *state = arg;

	if (nla_parse(msg_attr, NBD_ATTR_MAX, genlmsg_attrdata(gnlh, 0),
		      genlmsg_attrlen(gnlh, 0), NULL))
		return NL_OK;

	if (gnlh->cmd != NBD_CMD_LINK_DEAD)
		return NL_OK;
	if (!msg_attr[NBD_ATTR_INDEX])
		return NL_OK;
	if ((int)nla_get_u32(msg_attr[NBD_ATTR_INDEX]) != state->index)
		return NL_OK;

	state->link_dead = 1;
	return NL_OK;
}

/*
 * Establish a fresh set of connections to the server and negotiate them,
 * retrying with exponential backoff until all of them succeed. Returns 0
 * on success, or -1 when a signal told us to stop.
 */
static int persist_reconnect(int *sockfds) {
	int backoff = NBD_PERSIST_INITIAL_BACKOFF;

	fprintf(stderr, "Reconnecting %s\n", cur_client->dev);
	while (persist_running) {
		int i, failed = 0;

		for (i = 0; i < cur_client->nconn; i++) {
			if (cur_client->b_unix)
				sockfds[i] = openunix();
			else
				sockfds[i] = opennet();
			if (sockfds[i] < 0) {
				failed = 1;
				break;
			}
			if (!cur_client->preinit) {
				uint16_t new_flags = 0;
				negotiate(&sockfds[i], &new_flags, 0,
					  NBD_FLAG_C_FIXED_NEWSTYLE, 0);
			}
		}
		if (!failed)
			return 0;

		while (--i >= 0)
			close(sockfds[i]);
		fprintf(stderr, "Reconnecting failed, retrying in %d seconds\n",
			backoff);
		sleep(backoff);
		backoff *= 2;
		if (backoff > NBD_PERSIST_MAX_BACKOFF)
			backoff = NBD_PERSIST_MAX_BACKOFF;
	}

	return -1;
}

static int netlink_reconfigure(int index, int *sockfds,
			       const char *identifier) {
	struct nl_sock *socket;
	struct nlattr *sock_attr;
	struct nl_msg *msg;
