			for (i = 0; i < cur_client->nconn; i++)
				close(sockfds[i]);
			fprintf(stderr, "Reconnected %s\n", cur_client->dev);
			return 0;
		}

		/* Reconfiguring failed. If the device was disconnected in
		 * the meantime there is nothing to reconfigure anymore;
		 * otherwise just retry. */
		for (i = 0; i < cur_client->nconn; i++)
			close(sockfds[i]);
		if (!persist_running ||
		    netlink_check_conn(cur_client->dev, 0) == 1)
			return -1;
		sleep(backoff);
		backoff *= 2;
		if (backoff > NBD_PERSIST_MAX_BACKOFF)
			backoff = NBD_PERSIST_MAX_BACKOFF;
	}
}

