static int validate_reconfigure_message(struct nl_msg *msg) {
	struct nlmsghdr *nlh;
	struct genlmsghdr *gnlh;
	struct nlattr *attrs[NBD_ATTR_MAX + 1];
	struct nlattr *attr;
	int ret, rem;
	int nsocks = 0;

	nlh = real_nlmsg_hdr(msg);
	if (!nlh) return -1;

	gnlh = nlmsg_data(nlh);
	if (!gnlh) return -1;

	if (gnlh->cmd != NBD_CMD_RECONFIGURE) {
		fprintf(stderr, "MOCK: Expected NBD_CMD_RECONFIGURE, got %d\n", gnlh->cmd);
		return -1;
	}

	ret = genlmsg_parse(nlh, 0, attrs, NBD_ATTR_MAX, NULL);
	if (ret != 0) {
		fprintf(stderr, "MOCK: Failed to parse reconfigure attributes: %d\n", ret);
		return -1;
	}

	if (!attrs[NBD_ATTR_INDEX]) {
		fprintf(stderr, "MOCK: Missing required NBD_ATTR_INDEX for reconfigure\n");
		return -1;
	}

	if (!attrs[NBD_ATTR_SOCKETS]) {
		fprintf(stderr, "MOCK: Missing required NBD_ATTR_SOCKETS for reconfigure\n");
		return -1;
	}

	nla_for_each_nested(attr, attrs[NBD_ATTR_SOCKETS], rem) {
		struct nlattr *socks[NBD_SOCK_MAX + 1];

		if (nla_type(attr) != NBD_SOCK_ITEM)
			continue;
		if (nla_parse_nested(socks, NBD_SOCK_MAX, attr, NULL) != 0)
			continue;
		if (!socks[NBD_SOCK_FD]) {
			fprintf(stderr, "MOCK: Reconfigure socket item without NBD_SOCK_FD\n");
			return -1;
		}
		nsocks++;
	}

	if (nsocks == 0) {
		fprintf(stderr, "MOCK: Reconfigure message carries no sockets\n");
		return -1;
	}

	/* A successful reconfigure leaves the device connected */
	mock_device_status = 1;

	printf("MOCK: ✓ Reconfigure message validation passed\n");
	printf("MOCK:   Device index: %u, New sockets: %d\n",
	       nla_get_u32(attrs[NBD_ATTR_INDEX]), nsocks);

	return 0;
}

