#if HAVE_NETLINK
/*
 * Persistent mode for netlink-configured devices.
 *
 * The kernel nbd driver broadcasts an NBD_CMD_LINK_DEAD message, carrying
 * the device index, on the "nbd_mc_group" generic netlink multicast group
 * whenever it notices one of our connections has died. We subscribe to
 * that group and, upon receiving such a notification for our device,
 * reconnect to the server (with exponential backoff) and hand the new
 * sockets to the kernel via NBD_CMD_RECONFIGURE, so that queued I/O can
 * be retried over the new connections.
 */

/* Delay before the first reconnection attempt, and upper bound for the
 * exponential backoff, in seconds. */
#define NBD_PERSIST_INITIAL_BACKOFF	1
#define NBD_PERSIST_MAX_BACKOFF		180

/* While waiting for link-dead events, how often (in seconds) to check
 * whether the device was disconnected out from under us (e.g. through
 * "nbd-client -d"); no events are sent for those. */
#define NBD_PERSIST_POLL_INTERVAL	30

static volatile sig_atomic_t persist_running = 1;

static void persist_stop(int sig G_GNUC_UNUSED) {
	persist_running = 0;
}

struct persist_state {
	int index;
	int link_dead;
};

static int persist_event_callback(struct nl_msg *msg, void *arg) {
	struct genlmsghdr *gnlh = nlmsg_data(nlmsg_hdr(msg));
	struct nlattr *msg_attr[NBD_ATTR_MAX + 1];
	struct persist_state *state = arg;

	if (nla_parse(msg_attr, NBD_ATTR_MAX, genlmsg_attrdata(gnlh, 0),
		      genlmsg_attrlen(gnlh, 0), NULL))
		return NL_OK;

	if (gnlh->cmd != NBD_CMD_LINK_DEAD)
		return NL_OK;
	if (!msg_attr[NBD_ATTR_INDEX])
		return NL_OK;
	if ((int)nla_get_u32(msg_attr[NBD_ATTR_INDEX]) != state->index)
		return NL_OK;

	state->link_dead = 1;
	return NL_OK;
}

/*
 * Establish a fresh set of connections to the server and negotiate them,
 * retrying with exponential backoff until all of them succeed. Returns 0
 * on success, or -1 when a signal told us to stop.
 */
static int persist_reconnect(int *sockfds) {
	int backoff = NBD_PERSIST_INITIAL_BACKOFF;

	fprintf(stderr, "Reconnecting %s\n", cur_client->dev);
	while (persist_running) {
		int i, failed = 0;

		for (i = 0; i < cur_client->nconn; i++) {
			if (cur_client->b_unix)
				sockfds[i] = openunix();
			else
				sockfds[i] = opennet();
			if (sockfds[i] < 0) {
				failed = 1;
				break;
			}
			if (!cur_client->preinit) {
				uint16_t new_flags = 0;
				negotiate(&sockfds[i], &new_flags, 0,
					  NBD_FLAG_C_FIXED_NEWSTYLE, 0);
			}
		}
		if (!failed)
			return 0;

		while (--i >= 0)
			close(sockfds[i]);
		fprintf(stderr, "Reconnecting failed, retrying in %d seconds\n",
			backoff);
		sleep(backoff);
		backoff *= 2;
		if (backoff > NBD_PERSIST_MAX_BACKOFF)
			backoff = NBD_PERSIST_MAX_BACKOFF;
	}

	return -1;
}

static int netlink_reconfigure(int index, int *sockfds,
			       const char *identifier) {
	struct nl_sock *socket;
	struct nlattr *sock_attr;
	struct nl_msg *msg;
	int driver_id, i;
	int ret;

	socket = get_nbd_socket(&driver_id);

	msg = nlmsg_alloc();
	if (!msg)
		err("Couldn't allocate netlink message\n");
	genlmsg_put(msg, NL_AUTO_PORT, NL_AUTO_SEQ, driver_id, 0, 0,
		    NBD_CMD_RECONFIGURE, 0);
	NLA_PUT_U32(msg, NBD_ATTR_INDEX, index);
	if (identifier)
		NLA_PUT_STRING(msg, NBD_ATTR_BACKEND_IDENTIFIER, identifier);

	sock_attr = nla_nest_start(msg, NBD_ATTR_SOCKETS);
	if (!sock_attr)
		err("Couldn't nest the sockets for our connection\n");
	for (i = 0; i < cur_client->nconn; i++) {
		struct nlattr *sock_opt;
		sock_opt = nla_nest_start(msg, NBD_SOCK_ITEM);
		if (!sock_opt)
			err("Couldn't nest the sockets for our connection\n");
		NLA_PUT_U32(msg, NBD_SOCK_FD, sockfds[i]);
		nla_nest_end(msg, sock_opt);
	}
	nla_nest_end(msg, sock_attr);

	ret = nl_send_sync(socket, msg);
	nl_socket_free(socket);
	if (ret < 0) {
		fprintf(stderr, "Failed to reconfigure device: %s\n",
			nl_geterror(ret));
		return -1;
	}
	return 0;
nla_put_failure:
	err("Failed to create netlink message\n");
}

/*
 * Handle a dead link: reconnect to the server and swap the new sockets
 * into the kernel. Returns 0 when the device is usable again, or -1 when
 * persisting should stop (signalled, or the device was disconnected).
 */
static int persist_restore_connection(int index, int *sockfds,
				      const char *identifier) {
	uint64_t old_size = cur_client->size64;
	int backoff = NBD_PERSIST_INITIAL_BACKOFF;
	int i;

	/* The link-dead event may have been queued while the device was
	 * being disconnected; don't reconnect in that case. */
	if (netlink_check_conn(cur_client->dev, 0) == 1)
		return -1;

	for (;;) {
		if (persist_reconnect(sockfds))
			return -1;
		if (cur_client->size64 != old_size)
			err("Size of the device changed. Bye");

		if (netlink_reconfigure(index, sockfds, identifier) == 0) {
			for (i = 0; i < cur_client->nconn; i++)
				close(sockfds[i]);
			fprintf(stderr, "Reconnected %s\n", cur_client->dev);
			return 0;
		}

		/* Reconfiguring failed. If the device was disconnected in
		 * the meantime there is nothing to reconfigure anymore;
		 * otherwise just retry. */
		for (i = 0; i < cur_client->nconn; i++)
			close(sockfds[i]);
		if (!persist_running ||
		    netlink_check_conn(cur_client->dev, 0) == 1)
			return -1;
		sleep(backoff);
		backoff *= 2;
		if (backoff > NBD_PERSIST_MAX_BACKOFF)
			backoff = NBD_PERSIST_MAX_BACKOFF;
	}
}

static int netlink_persist(int index, const char *identifier) {
	struct persist_state state;
	struct sigaction sa;
	struct nl_sock *socket;
	int driver_id, group;
	int *sockfds;
	int ret;

	sockfds = malloc(sizeof(int) * cur_client->nconn);
	if (!sockfds)
		err("Cannot allocate the socket fd's array");

	memset(&state, 0, sizeof(state));
	state.index = index;

	socket = get_nbd_socket(&driver_id);
	group = genl_ctrl_resolve_grp(socket, NBD_GENL_FAMILY_NAME,
				      NBD_GENL_MCAST_GROUP_NAME);
	if (group < 0)
		err("Couldn't resolve the nbd netlink multicast group\n");
	if (nl_socket_add_membership(socket, group) < 0)
		err("Couldn't join the nbd netlink multicast group\n");
	nl_socket_disable_seq_check(socket);
	nl_socket_modify_cb(socket, NL_CB_VALID, NL_CB_CUSTOM,
			    persist_event_callback, &state);

	memset(&sa, 0, sizeof(sa));
	sa.sa_handler = persist_stop;
	sigaction(SIGINT, &sa, NULL);
	sigaction(SIGTERM, &sa, NULL);
	signal(SIGPIPE, SIG_IGN);
	/* Reconnecting a TLS connection forks one proxy per connection;
	 * don't accumulate those as zombies. */
	signal(SIGCHLD, SIG_IGN);

	fprintf(stderr, "Monitoring %s; will reconnect if the link dies\n",
		cur_client->dev);

	while (persist_running) {
		struct pollfd pfd;
		int have_events = 0;

		pfd.fd = nl_socket_get_fd(socket);
		pfd.events = POLLIN;
		pfd.revents = 0;

		ret = poll(&pfd, 1, NBD_PERSIST_POLL_INTERVAL * 1000);
		if (ret < 0) {
			if (errno == EINTR)
				continue;
			err_nonfatal("poll on netlink socket failed: %m");
			break;
		}

		if (ret > 0 && (pfd.revents & POLLIN)) {
			have_events = 1;
			ret = nl_recvmsgs_default(socket);
			if (ret < 0 && ret != NLE_INTR) {
				fprintf(stderr,
					"Error receiving netlink message: %s\n",
					nl_geterror(ret));
				break;
			}
		}

		if (state.link_dead) {
			state.link_dead = 0;
			fprintf(stderr, "Link to %s is dead\n",
				cur_client->dev);
			if (persist_restore_connection(index, sockfds,
						       identifier))
				break;
			continue;
		}

		if (!have_events &&
		    netlink_check_conn(cur_client->dev, 0) == 1) {
			fprintf(stderr,
				"%s was disconnected, stopping persist mode\n",
				cur_client->dev);
			break;
		}
	}

	nl_socket_free(socket);
	free(sockfds);
	return 0;
}
#endif /* HAVE_NETLINK */

